splash_code:
height: Fill
flow: Down
spacing: 10
padding: Inset{left: 16 right: 16 top: 16 bottom: 16}

fn press_num(d) {
    if mod.state.app.new_entry {
        mod.state.app.val = d
        mod.state.app.display = "" + d
        mod.state.app.new_entry = false
        mod.state.app.dec_mode = false
        mod.state.app.dec_place = 10
    }
    else if mod.state.app.dec_mode {
        mod.state.app.val = mod.state.app.val + d / mod.state.app.dec_place
        mod.state.app.dec_place = mod.state.app.dec_place * 10
        mod.state.app.display = mod.state.app.display + d
    }
    else {
        mod.state.app.val = mod.state.app.val * 10 + d
        mod.state.app.display = "" + mod.state.app.val
    }
    mod.state.app.version = mod.state.app.version + 1
}

fn press_dot() {
    if !mod.state.app.dec_mode {
        mod.state.app.dec_mode = true
        mod.state.app.dec_place = 10
        mod.state.app.display = mod.state.app.display + "."
        mod.state.app.version = mod.state.app.version + 1
    }
}

fn press_op(o) {
    mod.state.app.first = mod.state.app.val
    mod.state.app.op = o
    mod.state.app.val = 0
    mod.state.app.dec_mode = false
    mod.state.app.dec_place = 10
    mod.state.app.new_entry = true
    mod.state.app.history = mod.state.app.display + " " + o
    mod.state.app.version = mod.state.app.version + 1
}

fn press_eq() {
    let a = mod.state.app.first
    let b = mod.state.app.val
    let o = mod.state.app.op
    if o == "+" {
        mod.state.app.val = a + b
        mod.state.app.display = "" + (a + b)
    }
    if o == "-" {
        mod.state.app.val = a - b
        mod.state.app.display = "" + (a - b)
    }
    if o == "*" {
        mod.state.app.val = a * b
        mod.state.app.display = "" + (a * b)
    }
    if o == "/" {
        if b == 0 {
            mod.state.app.display = "Error"
        }
        else {
            mod.state.app.val = a / b
            mod.state.app.display = "" + (a / b)
        }
    }
    mod.state.app.history = mod.state.app.history + " " + b + " ="
    mod.state.app.op = ""
    mod.state.app.new_entry = true
    mod.state.app.dec_mode = false
    mod.state.app.dec_place = 10
    mod.state.app.version = mod.state.app.version + 1
}

fn press_clear() {
    mod.state.app.val = 0
    mod.state.app.first = 0
    mod.state.app.op = ""
    mod.state.app.display = "0"
    mod.state.app.history = ""
    mod.state.app.new_entry = true
    mod.state.app.dec_mode = false
    mod.state.app.dec_place = 10
    mod.state.app.version = mod.state.app.version + 1
}

fn press_back() {
    let d = mod.state.app.display
    let parts = d.split(".")
    if parts[1] != nil {
        mod.state.app.dec_mode = false
        mod.state.app.display = parts[0]
        mod.state.app.val = mod.state.app.val - (mod.state.app.val - math.floor(mod.state.app.val))
    }
    else if d.len() > 1 {
        mod.state.app.val = math.floor(mod.state.app.val / 10)
        mod.state.app.display = "" + mod.state.app.val
    }
    else {
        mod.state.app.val = 0
        mod.state.app.display = "0"
    }
    mod.state.app.version = mod.state.app.version + 1
}

View{
    width: Fill height: Fit flow: Down spacing: 4
    padding: Inset{left: 20 right: 20 top: 20 bottom: 16}
    show_bg: true new_batch: true
    draw_bg +: { color: #x1e293b radius: 14.0 }

    Label{
        width: Fill
        text: "" + mod.state.app.history
        draw_text +: { text_style: theme.font_regular {font_size: 13} color: #x64748b }
    }
    Label{
        width: Fill
        text: "" + mod.state.app.display
        draw_text +: { text_style: theme.font_bold {font_size: 48} color: #xf1f5f9 }
    }
}

